export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  /** Path of source file relative to the source dir, e.g. "posts/hello.md" */
  sourcePath: string;
  /** Output path relative to the out dir, e.g. "posts/hello/index.html" */
  outputPath: string;
  /** Site-absolute URL, e.g. "/posts/hello/" */
  url: string;
  frontmatter: Frontmatter;
  /** Raw markdown body (without frontmatter) */
  body: string;
  /** Rendered HTML body */
  html: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  baseUrl: string;
  siteTitle: string;
  siteDescription: string;
  includeDrafts: boolean;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  filesWritten: string[];
}

import matter from "gray-matter";
import type { Frontmatter } from "./types.js";

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

function toDate(value: unknown): Date | null {
  if (value instanceof Date && !isNaN(value.getTime())) return value;
  if (typeof value === "string" || typeof value === "number") {
    const d = new Date(value);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
}

function toTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((t) => String(t).trim()).filter(Boolean);
  }
  if (typeof value === "string") {
    return value
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

function toBool(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") return value.trim().toLowerCase() === "true";
  return false;
}

/**
 * Parse a markdown document with optional YAML frontmatter.
 * Normalizes the well-known fields: title, date, tags, draft.
 * Unknown fields are passed through untouched.
 */
export function parseFrontmatter(raw: string, fallbackTitle = "Untitled"): ParsedDocument {
  const { data, content } = matter(raw);
  const { title, date, tags, draft, ...rest } = data as Record<string, unknown>;
  const frontmatter: Frontmatter = {
    ...rest,
    title: typeof title === "string" && title.trim() ? title.trim() : fallbackTitle,
    date: toDate(date),
    tags: toTags(tags),
    draft: toBool(draft),
  };
  if (typeof data.layout === "string") frontmatter.layout = data.layout;
  return { frontmatter, body: content };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code, lang) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

/** Render markdown to HTML with syntax-highlighted code blocks. */
export function renderMarkdown(md: string): string {
  return marked.parse(md, { async: false }) as string;
}

import Handlebars from "handlebars";
import fs from "node:fs";
import path from "node:path";

export interface TemplateEngine {
  /** Render a named template (e.g. "post") with a context, wrapped in its layout. */
  render(name: string, context: Record<string, unknown>, layoutName?: string): string;
  hasTemplate(name: string): boolean;
}

const FALLBACK_LAYOUT = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{title}}</title>
</head>
<body>
{{{body}}}
</body>
</html>`;

const FALLBACK_PAGE = `<article><h1>{{page.frontmatter.title}}</h1>{{{page.html}}}</article>`;

const FALLBACK_TAG = `<h1>Tag: {{tag}}</h1>
<ul>
{{#each pages}}<li><a href="{{url}}">{{frontmatter.title}}</a></li>
{{/each}}
</ul>`;

const FALLBACK_INDEX = `<h1>{{site.title}}</h1>
<ul>
{{#each pages}}<li><a href="{{url}}">{{frontmatter.title}}</a>{{#if frontmatter.date}} — {{formatDate frontmatter.date}}{{/if}}</li>
{{/each}}
</ul>`;

function registerHelpers(hbs: typeof Handlebars): void {
  hbs.registerHelper("formatDate", (date: unknown, fmt?: unknown) => {
    if (!(date instanceof Date) || isNaN(date.getTime())) return "";
    if (typeof fmt === "string" && fmt === "iso") return date.toISOString();
    return date.toISOString().slice(0, 10);
  });
  hbs.registerHelper("join", (arr: unknown, sep: unknown) =>
    Array.isArray(arr) ? arr.join(typeof sep === "string" ? sep : ", ") : ""
  );
  hbs.registerHelper("eq", (a: unknown, b: unknown) => a === b);
}

/**
 * Load a Handlebars template environment from a directory.
 *
 * Convention:
 *   templates/
 *     layouts/    -> layouts ({{{body}}} receives the rendered page); default.hbs used unless overridden
 *     partials/   -> registered as partials by file name (without extension)
 *     *.hbs       -> page templates (post.hbs, index.hbs, tag.hbs, ...)
 *
 * Missing templates fall back to minimal built-ins so a bare source dir still builds.
 */
export function createTemplateEngine(templateDir: string): TemplateEngine {
  const hbs = Handlebars.create();
  registerHelpers(hbs);

  const templates = new Map<string, Handlebars.TemplateDelegate>();
  const layouts = new Map<string, Handlebars.TemplateDelegate>();

  const readHbsFiles = (dir: string): Array<{ name: string; source: string }> => {
    if (!fs.existsSync(dir)) return [];
    return fs
      .readdirSync(dir)
      .filter((f) => /\.(hbs|handlebars|html)$/.test(f))
      .map((f) => ({
        name: f.replace(/\.(hbs|handlebars|html)$/, ""),
        source: fs.readFileSync(path.join(dir, f), "utf8"),
      }));
  };

  for (const { name, source } of readHbsFiles(path.join(templateDir, "partials"))) {
    hbs.registerPartial(name, source);
  }
  for (const { name, source } of readHbsFiles(path.join(templateDir, "layouts"))) {
    layouts.set(name, hbs.compile(source));
  }
  for (const { name, source } of readHbsFiles(templateDir)) {
    templates.set(name, hbs.compile(source));
  }

  if (!layouts.has("default")) layouts.set("default", hbs.compile(FALLBACK_LAYOUT));
  if (!templates.has("post")) templates.set("post", hbs.compile(FALLBACK_PAGE));
  if (!templates.has("page")) templates.set("page", hbs.compile(FALLBACK_PAGE));
  if (!templates.has("tag")) templates.set("tag", hbs.compile(FALLBACK_TAG));
  if (!templates.has("index")) templates.set("index", hbs.compile(FALLBACK_INDEX));

  return {
    hasTemplate: (name) => templates.has(name),
    render(name, context, layoutName = "default") {
      const template = templates.get(name);
      if (!template) throw new Error(`Unknown template: ${name}`);
      const body = template(context);
      const layout = layouts.get(layoutName) ?? layouts.get("default")!;
      return layout({ ...context, body });
    },
  };
}

import type { Page, SiteConfig } from "./types.js";

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function absUrl(baseUrl: string, url: string): string {
  return baseUrl.replace(/\/$/, "") + url;
}

/** Generate an RSS 2.0 feed for the given pages (assumed already sorted, drafts excluded). */
export function generateRss(pages: Page[], config: SiteConfig, limit = 20): string {
  const items = pages.slice(0, limit).map((page) => {
    const link = absUrl(config.baseUrl, page.url);
    const pubDate = page.frontmatter.date ? page.frontmatter.date.toUTCString() : "";
    return [
      "    <item>",
      `      <title>${escapeXml(page.frontmatter.title)}</title>`,
      `      <link>${escapeXml(link)}</link>`,
      `      <guid>${escapeXml(link)}</guid>`,
      pubDate ? `      <pubDate>${pubDate}</pubDate>` : "",
      page.frontmatter.tags.map((t) => `      <category>${escapeXml(t)}</category>`).join("\n"),
      `      <description><![CDATA[${page.html}]]></description>`,
      "    </item>",
    ]
      .filter(Boolean)
      .join("\n");
  });

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(config.baseUrl)}</link>
    <description>${escapeXml(config.siteDescription)}</description>
    <atom:link href="${escapeXml(absUrl(config.baseUrl, "/feed.xml"))}" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items.join("\n")}
  </channel>
</rss>
`;
}

import fs from "node:fs";
import path from "node:path";
import { parseFrontmatter } from "./frontmatter.js";
import { renderMarkdown } from "./markdown.js";
import { createTemplateEngine, type TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";
import type { BuildResult, Page, SiteConfig } from "./types.js";

function walk(dir: string, base = dir): string[] {
  if (!fs.existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full, base));
    else if (/\.(md|markdown)$/.test(entry.name)) out.push(path.relative(base, full));
  }
  return out.sort();
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function urlFor(sourcePath: string): { url: string; outputPath: string } {
  const noExt = sourcePath.replace(/\.(md|markdown)$/, "").split(path.sep).join("/");
  if (noExt === "index" || noExt.endsWith("/index")) {
    const dir = noExt === "index" ? "" : noExt.slice(0, -"/index".length);
    return { url: `/${dir}${dir ? "/" : ""}`, outputPath: path.join(dir, "index.html") };
  }
  return { url: `/${noExt}/`, outputPath: path.join(noExt, "index.html") };
}

/** Load and render all markdown pages from the source directory. */
export function loadPages(config: SiteConfig): Page[] {
  const files = walk(config.sourceDir);
  const pages: Page[] = [];
  for (const rel of files) {
    const raw = fs.readFileSync(path.join(config.sourceDir, rel), "utf8");
    const fallbackTitle = path.basename(rel).replace(/\.(md|markdown)$/, "");
    const { frontmatter, body } = parseFrontmatter(raw, fallbackTitle);
    if (frontmatter.draft && !config.includeDrafts) continue;
    const { url, outputPath } = urlFor(rel);
    pages.push({ sourcePath: rel, outputPath, url, frontmatter, body, html: renderMarkdown(body) });
  }
  // Newest first; undated pages sink to the bottom.
  pages.sort((a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0));
  return pages;
}

/** Group pages by tag (tag -> pages, preserving date order). */
export function collectTags(pages: Page[]): Map<string, Page[]> {
  const tags = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      if (!tags.has(tag)) tags.set(tag, []);
      tags.get(tag)!.push(page);
    }
  }
  return new Map([...tags.entries()].sort(([a], [b]) => a.localeCompare(b)));
}

function writeFile(outDir: string, relPath: string, content: string, written: string[]): void {
  const full = path.join(outDir, relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
  written.push(relPath);
}

/** Build the whole site: pages, index, tag pages, RSS feed. */
export function buildSite(config: SiteConfig, engine?: TemplateEngine): BuildResult {
  const tpl = engine ?? createTemplateEngine(config.templateDir);
  const pages = loadPages(config);
  const tags = collectTags(pages);
  const written: string[] = [];

  const site = {
    title: config.siteTitle,
    description: config.siteDescription,
    baseUrl: config.baseUrl,
    tags: [...tags.keys()],
  };

  const indexPage = pages.find((p) => p.url === "/");
  const contentPages = pages.filter((p) => p !== indexPage);

  for (const page of pages) {
    const templateName =
      typeof page.frontmatter.template === "string" && tpl.hasTemplate(page.frontmatter.template)
        ? (page.frontmatter.template as string)
        : tpl.hasTemplate("post")
          ? "post"
          : "page";
    const html = tpl.render(
      templateName,
      { site, page, pages: contentPages, title: page.frontmatter.title },
      page.frontmatter.layout
    );
    writeFile(config.outDir, page.outputPath, html, written);
  }

  if (!indexPage) {
    const html = tpl.render("index", { site, pages: contentPages, title: config.siteTitle });
    writeFile(config.outDir, "index.html", html, written);
  }

  const tagPages: string[] = [];
  for (const [tag, tagged] of tags) {
    const slug = slugify(tag);
    const outPath = path.join("tags", slug, "index.html");
    const html = tpl.render("tag", { site, tag, pages: tagged, title: `Tag: ${tag}` });
    writeFile(config.outDir, outPath, html, written);
    tagPages.push(`/tags/${slug}/`);
  }

  const feedPages = contentPages.filter((p) => !p.frontmatter.draft);
  writeFile(config.outDir, "feed.xml", generateRss(feedPages, config), written);

  return { pages, tagPages, filesWritten: written };
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer } from "ws";
import { buildSite } from "./build.js";
import type { SiteConfig } from "./types.js";

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml; charset=utf-8",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};

export const RELOAD_SCRIPT = `<script>
(() => {
  const ws = new WebSocket("ws://" + location.host + "/__livereload");
  ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
  ws.onclose = () => setTimeout(() => location.reload(), 1000);
})();
</script>`;

/** Inject the live-reload script before </body> (or append if absent). */
export function injectReloadScript(html: string): string {
  if (html.includes("</body>")) return html.replace("</body>", `${RELOAD_SCRIPT}\n</body>`);
  return html + RELOAD_SCRIPT;
}

export interface DevServer {
  close(): Promise<void>;
  port: number;
}

/**
 * Serve the output directory with live reload. Watches source + template dirs
 * with chokidar, rebuilds on change, and broadcasts "reload" over WebSocket.
 */
export async function startDevServer(config: SiteConfig, port: number): Promise<DevServer> {
  buildSite(config);

  const server = http.createServer((req, res) => {
    const urlPath = decodeURIComponent((req.url ?? "/").split("?")[0]);
    let filePath = path.join(config.outDir, path.normalize(urlPath).replace(/^(\.\.[/\\])+/, ""));
    if (!filePath.startsWith(path.resolve(config.outDir)) && !filePath.startsWith(config.outDir)) {
      res.writeHead(403).end("Forbidden");
      return;
    }
    if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
      filePath = path.join(filePath, "index.html");
    }
    if (!fs.existsSync(filePath)) {
      res.writeHead(404, { "Content-Type": "text/html" });
      res.end(injectReloadScript("<h1>404 Not Found</h1>"));
      return;
    }
    const ext = path.extname(filePath);
    const type = MIME[ext] ?? "application/octet-stream";
    let content: Buffer | string = fs.readFileSync(filePath);
    if (ext === ".html") content = injectReloadScript(content.toString("utf8"));
    res.writeHead(200, { "Content-Type": type });
    res.end(content);
  });

  const wss = new WebSocketServer({ server, path: "/__livereload" });
  const broadcast = () => {
    for (const client of wss.clients) {
      if (client.readyState === 1) client.send("reload");
    }
  };

  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 20 },
  });
  let timer: ReturnType<typeof setTimeout> | null = null;
  watcher.on("all", (event, file) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      try {
        console.log(`[ssg] ${event}: ${file} — rebuilding`);
        buildSite(config);
        broadcast();
      } catch (err) {
        console.error("[ssg] rebuild failed:", err);
      }
    }, 50);
  });

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const actualPort = (server.address() as { port: number }).port;
  console.log(`[ssg] dev server: http://localhost:${actualPort}`);

  return {
    port: actualPort,
    async close() {
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve, reject) =>
        server.close((err) => (err ? reject(err) : resolve()))
      );
    },
  };
}

#!/usr/bin/env node
import { Command } from "commander";
import path from "node:path";
import { buildSite } from "./build.js";
import { startDevServer } from "./server.js";
import type { SiteConfig } from "./types.js";

interface CommonOpts {
  source: string;
  templates: string;
  out: string;
  baseUrl: string;
  title: string;
  description: string;
  drafts: boolean;
}

function toConfig(opts: CommonOpts): SiteConfig {
  return {
    sourceDir: path.resolve(opts.source),
    templateDir: path.resolve(opts.templates),
    outDir: path.resolve(opts.out),
    baseUrl: opts.baseUrl,
    siteTitle: opts.title,
    siteDescription: opts.description,
    includeDrafts: opts.drafts,
  };
}

function addCommonOptions(cmd: Command): Command {
  return cmd
    .option("-s, --source <dir>", "source directory of markdown files", "content")
    .option("-t, --templates <dir>", "handlebars template directory", "templates")
    .option("-o, --out <dir>", "output directory", "dist-site")
    .option("--base-url <url>", "site base URL for absolute links/RSS", "http://localhost:3000")
    .option("--title <title>", "site title", "My Site")
    .option("--description <desc>", "site description", "")
    .option("--drafts", "include draft pages", false);
}

export function createProgram(): Command {
  const program = new Command();
  program.name("ssg").description("Static site generator: Markdown + Handlebars").version("1.0.0");

  addCommonOptions(program.command("build").description("build the site"))
    .action((opts: CommonOpts) => {
      const config = toConfig(opts);
      const result = buildSite(config);
      console.log(`[ssg] built ${result.filesWritten.length} files to ${config.outDir}`);
    });

  addCommonOptions(program.command("serve").description("build and serve with live reload"))
    .option("-p, --port <port>", "port to listen on", "3000")
    .action(async (opts: CommonOpts & { port: string }) => {
      await startDevServer(toConfig(opts), parseInt(opts.port, 10));
    });

  return program;
}

const isMain = process.argv[1] && import.meta.url.endsWith(path.basename(process.argv[1]));
if (isMain) {
  createProgram().parseAsync(process.argv).catch((err) => {
    console.error("[ssg] error:", err instanceof Error ? err.message : err);
    process.exit(1);
  });
}

import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("parses title, date, tags, draft", () => {
    const { frontmatter, body } = parseFrontmatter(
      `---
title: Hello World
date: 2024-03-15
tags: [ts, node]
draft: true
---
Body text.`
    );
    expect(frontmatter.title).toBe("Hello World");
    expect(frontmatter.date).toBeInstanceOf(Date);
    expect(frontmatter.date!.toISOString().slice(0, 10)).toBe("2024-03-15");
    expect(frontmatter.tags).toEqual(["ts", "node"]);
    expect(frontmatter.draft).toBe(true);
    expect(body.trim()).toBe("Body text.");
  });

  it("handles missing frontmatter with defaults", () => {
    const { frontmatter, body } = parseFrontmatter("Just markdown.", "fallback");
    expect(frontmatter.title).toBe("fallback");
    expect(frontmatter.date).toBeNull();
    expect(frontmatter.tags).toEqual([]);
    expect(frontmatter.draft).toBe(false);
    expect(body).toBe("Just markdown.");
  });

  it("parses comma-separated tag strings", () => {
    const { frontmatter } = parseFrontmatter(`---\ntags: a, b , c\n---\nx`);
    expect(frontmatter.tags).toEqual(["a", "b", "c"]);
  });

  it("coerces draft strings and rejects invalid dates", () => {
    const { frontmatter } = parseFrontmatter(`---\ndraft: "true"\ndate: not-a-date\n---\nx`);
    expect(frontmatter.draft).toBe(true);
    expect(frontmatter.date).toBeNull();
  });

  it("passes through custom fields and layout", () => {
    const { frontmatter } = parseFrontmatter(`---\nlayout: wide\nauthor: Ada\n---\nx`);
    expect(frontmatter.layout).toBe("wide");
    expect(frontmatter.author).toBe("Ada");
  });

  it("trims whitespace-only titles to fallback", () => {
    const { frontmatter } = parseFrontmatter(`---\ntitle: "   "\n---\nx`, "fb");
