import { describe, it, expect, beforeAll, afterAll } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createTemplateEngine } from "../src/templates.js";

let dir: string;

beforeAll(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-tpl-"));
  fs.mkdirSync(path.join(dir, "layouts"));
  fs.mkdirSync(path.join(dir, "partials"));
  fs.writeFileSync(
    path.join(dir, "layouts", "default.hbs"),
    `<html><title>{{title}}</title><body>{{> header}}{{{body}}}</body></html>`
  );
  fs.writeFileSync(
    path.join(dir, "layouts", "wide.hbs"),
    `<html><body class="wide">{{{body}}}</body></html>`
  );
  fs.writeFileSync(path.join(dir, "partials", "header.hbs"), `<header>{{site.title}}</header>`);
  fs.writeFileSync(path.join(dir, "post.hbs"), `<article>{{page.frontmatter.title}}:{{{page.html}}}</article>`);
});

afterAll(() => fs.rmSync(dir, { recursive: true, force: true }));

describe("template engine", () => {
  it("renders a template inside its layout with partials", () => {
    const engine = createTemplateEngine(dir);
    const html = engine.render("post", {
      title: "T",
      site: { title: "Site" },
      page: { frontmatter: { title: "Post" }, html: "<p>hi</p>" },
    });
    expect(html).toContain("<title>T</title>");
    expect(html).toContain("<header>Site</header>");
    expect(html).toContain("<article>Post:<p>hi</p></article>");
  });

  it("supports selecting an alternate layout", () => {
    const engine = createTemplateEngine(dir);
    const html = engine.render(
      "post",
      { page: { frontmatter: { title: "P" }, html: "" } },
      "wide"
    );
    expect(html).toContain('class="wide"');
  });

  it("falls back to default layout for unknown layout names", () => {
    const engine = createTemplateEngine(dir);
    const html = engine.render(
      "post",
      { title: "X", site: {}, page: { frontmatter: { title: "P" }, html: "" } },
      "nope"
    );
    expect(html).toContain("<title>X</title>");
  });

  it("provides built-in fallbacks when template dir is empty", () => {
    const empty = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-empty-"));
    const engine = createTemplateEngine(empty);
    const html = engine.render("tag", {
      tag: "ts",
      pages: [{ url: "/a/", frontmatter: { title: "A" } }],
    });
    expect(html).toContain("Tag: ts");
    expect(html).toContain('<a href="/a/">A</a>');
    fs.rmSync(empty, { recursive: true, force: true });
  });

  it("does not escape triple-stash HTML but escapes double-stash", () => {
    const engine = createTemplateEngine(dir);
    const html = engine.render("post", {
      page: { frontmatter: { title: "<b>" }, html: "<em>ok</em>" },
    });
    expect(html).toContain("&lt;b&gt;");
    expect(html).toContain("<em>ok</em>");
  });

  it("formatDate helper formats dates", () => {
    const empty = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-fd-"));
    fs.writeFileSync(path.join(empty, "index.hbs"), `{{formatDate d}}|{{formatDate d "iso"}}`);
    const engine = createTemplateEngine(empty);
    const out = engine.render("index", { d: new Date("2024-01-02T03:04:05Z") });
    expect(out).toContain("2024-01-02|2024-01-02T03:04:05.000Z");
    fs.rmSync(empty, { recursive: true, force: true });
  });

  it("throws on unknown template names", () => {
    const engine = createTemplateEngine(dir);
    expect(() => engine.render("missing", {})).toThrow(/Unknown template/);
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { buildSite, collectTags, loadPages, slugify } from "../src/build.js";
import { renderMarkdown } from "../src/markdown.js";
import { generateRss } from "../src/rss.js";
import type { SiteConfig } from "../src/types.js";

let root: string;
let config: SiteConfig;

function write(rel: string, content: string): void {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
}

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-build-"));
  config = {
    sourceDir: path.join(root, "content"),
    templateDir: path.join(root, "templates"),
    outDir: path.join(root, "out"),
    baseUrl: "https://example.com",
    siteTitle: "Test Site",
    siteDescription: "A test",
    includeDrafts: false,
  };
  write(
    "content/posts/hello.md",
    `---\ntitle: Hello\ndate: 2024-02-01\ntags: [typescript, web dev]\n---\n# Hi\n\n\`\`\`js\nconst x = 1;\n\`\`\`\n`
  );
  write("content/posts/older.md", `---\ntitle: Older\ndate: 2023-01-01\ntags: [typescript]\n---\nold`);
  write("content/secret.md", `---\ntitle: Secret\ndraft: true\ntags: [typescript]\n---\nshh`);
});

afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

describe("loadPages", () => {
  it("excludes drafts by default and sorts newest first", () => {
    const pages = loadPages(config);
    expect(pages.map((p) => p.frontmatter.title)).toEqual(["Hello", "Older"]);
  });

  it("includes drafts with includeDrafts", () => {
    const pages = loadPages({ ...config, includeDrafts: true });
    expect(pages.map((p) => p.frontmatter.title)).toContain("Secret");
  });

  it("computes pretty URLs and output paths", () => {
    const pages = loadPages(config);
    const hello = pages.find((p) => p.frontmatter.title === "Hello")!;
    expect(hello.url).toBe("/posts/hello/");
    expect(hello.outputPath).toBe(path.join("posts", "hello", "index.html"));
  });
});

describe("markdown + highlighting", () => {
  it("renders headings and syntax-highlighted code blocks", () => {
    const html = renderMarkdown("# Title\n\n```js\nconst x = 1;\n```\n");
    expect(html).toContain("<h1>Title</h1>");
    expect(html).toContain('class="hljs language-js"');
    expect(html).toContain("hljs-keyword");
  });
});

describe("buildSite", () => {
  it("writes page HTML, index, tag pages, and RSS", () => {
    const result = buildSite(config);
    const out = config.outDir;
    expect(fs.existsSync(path.join(out, "posts", "hello", "index.html"))).toBe(true);
    expect(fs.existsSync(path.join(out, "index.html"))).toBe(true);
    expect(fs.existsSync(path.join(out, "tags", "typescript", "index.html"))).toBe(true);
    expect(fs.existsSync(path.join(out, "tags", "web-dev", "index.html"))).toBe(true);
    expect(fs.existsSync(path.join(out, "feed.xml"))).toBe(true);
    expect(result.tagPages).toEqual(["/tags/typescript/", "/tags/web-dev/"]);
  });

  it("tag index lists only tagged, non-draft pages", () => {
    buildSite(config);
    const html = fs.readFileSync(path.join(config.outDir, "tags", "typescript", "index.html"), "utf8");
    expect(html).toContain("Hello");
    expect(html).toContain("Older");
    expect(html).not.toContain("Secret");
  });

  it("uses custom templates when provided", () => {
    write("templates/layouts/default.hbs", "<body data-layout>{{{body}}}</body>");
    write("templates/post.hbs", "<main>{{page.frontmatter.title}}</main>");
    buildSite(config);
    const html = fs.readFileSync(path.join(config.outDir, "posts", "hello", "index.html"), "utf8");
    expect(html).toContain("<body data-layout>");
    expect(html).toContain("<main>Hello</main>");
  });
});

describe("collectTags / slugify", () => {
  it("groups pages by tag alphabetically", () => {
    const tags = collectTags(loadPages(config));
    expect([...tags.keys()]).toEqual(["typescript", "web dev"]);
    expect(tags.get("typescript")!.length).toBe(2);
  });

  it("slugifies tags", () => {
    expect(slugify("Web Dev!")).toBe("web-dev");
    expect(slugify("C++ & Rust")).toBe("c-rust");
  });
});

describe("generateRss", () => {
  it("produces valid RSS with escaped fields and pubDates", () => {
    const pages = loadPages(config);
    const xml = generateRss(pages, config);
    expect(xml).toContain("<?xml version=");
    expect(xml).toContain("<title>Test Site</title>");
    expect(xml).toContain("<link>https://example.com/posts/hello/</link>");
    expect(xml).toContain("<pubDate>Thu, 01 Feb 2024");
    expect(xml).toContain("<category>typescript</category>");
    expect(xml).toContain("<![CDATA[");
  });

  it("escapes XML entities in titles", () => {
    write("content/amp.md", `---\ntitle: "Cats & <Dogs>"\ndate: 2024-05-05\n---\nx`);
    const xml = generateRss(loadPages(config), config);
    expect(xml).toContain("Cats &amp; &lt;Dogs&gt;");
  });

  it("respects the item limit", () => {
    const xml = generateRss(loadPages(config), config, 1);
    expect(xml.match(/<item>/g)?.length).toBe(1);
  });
});

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createProgram } from "../src/cli.js";

let root: string;

function write(rel: string, content: string): void {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content);
}

async function runCli(args: string[]): Promise<void> {
  const program = createProgram();
  program.exitOverride();
  await program.parseAsync(["node", "ssg", ...args]);
}

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-cli-"));
  write("content/a.md", `---\ntitle: A\ndate: 2024-01-01\ntags: [x]\n---\nhello`);
  write("content/d.md", `---\ntitle: D\ndraft: true\n---\nsecret`);
  vi.spyOn(console, "log").mockImplementation(() => {});
});

afterEach(() => {
  fs.rmSync(root, { recursive: true, force: true });
  vi.restoreAllMocks();
});

describe("ssg build flags", () => {
  it("--source/--templates/--out control directories", async () => {
    const out = path.join(root, "custom-out");
    await runCli(["build", "--source", path.join(root, "content"), "--templates", path.join(root, "tpl"), "--out", out]);
    expect(fs.existsSync(path.join(out, "a", "index.html"))).toBe(true);
    expect(fs.existsSync(path.join(out, "feed.xml"))).toBe(true);
  });

  it("excludes drafts by default, includes with --drafts", async () => {
    const out1 = path.join(root, "out1");
    await runCli(["build", "-s", path.join(root, "content"), "-t", path.join(root, "tpl"), "-o", out1]);
    expect(fs.existsSync(path.join(out1, "d", "index.html"))).toBe(false);

    const out2 = path.join(root, "out2");
    await runCli(["build", "-s", path.join(root, "content"), "-t", path.join(root, "tpl"), "-o", out2, "--drafts"]);
    expect(fs.existsSync(path.join(out2, "d", "index.html"))).toBe(true);
  });

  it("--base-url and --title feed into RSS output", async () => {
    const out = path.join(root, "out3");
    await runCli([
      "build", "-s", path.join(root, "content"), "-t", path.join(root, "tpl"), "-o", out,
      "--base-url", "https://blog.example", "--title", "My Blog",
    ]);
    const xml = fs.readFileSync(path.join(out, "feed.xml"), "utf8");
    expect(xml).toContain("<title>My Blog</title>");
    expect(xml).toContain("<link>https://blog.example/a/</link>");
  });

  it("rejects unknown flags", async () => {
    vi.spyOn(console, "error").mockImplementation(() => {});
    await expect(runCli(["build", "--bogus"])).rejects.toThrow();
  });

  it("prints a build summary", async () => {
    const log = vi.spyOn(console, "log").mockImplementation(() => {});
    const out = path.join(root, "out4");
    await runCli(["build", "-s", path.join(root, "content"), "-t", path.join(root, "tpl"), "-o", out]);
    expect(log.mock.calls.some(([msg]) => String(msg).includes("built"))).toBe(true);
  });
});

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { WebSocket } from "ws";
import { injectReloadScript, RELOAD_SCRIPT, startDevServer, type DevServer } from "../src/server.js";
import type { SiteConfig } from "../src/types.js";

describe("injectReloadScript", () => {
  it("injects before </body>", () => {
    const out = injectReloadScript("<html><body><p>x</p></body></html>");
    expect(out).toContain(RELOAD_SCRIPT);
    expect(out.indexOf(RELOAD_SCRIPT)).toBeLessThan(out.indexOf("</body>"));
  });

  it("appends when </body> is missing", () => {
    const out = injectReloadScript("<p>x</p>");
    expect(out.endsWith(RELOAD_SCRIPT)).toBe(true);
  });
});

describe("dev server", () => {
  let root: string;
  let server: DevServer;
  let config: SiteConfig;

  beforeAll(async () => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), "ssg-srv-"));
    fs.mkdirSync(path.join(root, "content"), { recursive: true });
    fs.writeFileSync(
      path.join(root, "content", "a.md"),
      `---\ntitle: A\ndate: 2024-01-01\n---\nhello world`
    );
    config = {
      sourceDir: path.join(root, "content"),
      templateDir: path.join(root, "templates"),
      outDir: path.join(root, "out"),
      baseUrl: "http://localhost",
      siteTitle: "S",
      siteDescription: "",
      includeDrafts: false,
    };
    server = await startDevServer(config, 0); // ephemeral port
  }, 15000);

  afterAll(async () => {
    await server.close();
    fs.rmSync(root, { recursive: true, force: true });
  });

  it("serves built pages with the reload script injected", async () => {
    const res = await fetch(`http://localhost:${server.port}/a/`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain("hello world");
    expect(html).toContain("__livereload");
  });

  it("serves feed.xml without injection", async () => {
    const res = await fetch(`http://localhost:${server.port}/feed.xml`);
    expect(res.status).toBe(200);
    expect(res.headers.get("content-type")).toContain("xml");
    expect(await res.text()).not.toContain("__livereload");
  });

  it("returns 404 with reload script for missing paths", async () => {
    const res = await fetch(`http://localhost:${server.port}/nope/`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("__livereload");
  });

  it("broadcasts reload over WebSocket when a source file changes", async () => {
    const ws = new WebSocket(`ws://localhost:${server.port}/__livereload`);
    await new Promise<void>((resolve, reject) => {
      ws.on("open", resolve);
      ws.on("error", reject);
    });
    const reload = new Promise<string>((resolve) =>
      ws.on("message", (data) => resolve(data.toString()))
    );
    fs.writeFileSync(
      path.join(config.sourceDir, "a.md"),
      `---\ntitle: A\ndate: 2024-01-01\n---\nhello again`
    );
    expect(await reload).toBe("reload");
    ws.close();

    const html = await (await fetch(`http://localhost:${server.port}/a/`)).text();
    expect(html).toContain("hello again");
  }, 15000);
});
